using HotChocolate.Authorization;
using GraphApi.Infrastructure.Services;using GraphApi.Models.SGR.Perfiles;using GraphApi.Services.SGR.Perfiles;using HotChocolate;using System.Linq;namespace GraphApi.GraphQL.SGR.Perfiles{    [MutationType]    [GraphQLDescription("Punto de entrada para las mutaciones de Perfiles: creación, actualización y eliminación.")]    public class PerfilesMutation    {        [Authorize]        [GraphQLName("createPerfiles")]        [GraphQLDescription("Crea un nuevo Perfile usando los headers 'UserID' y 'WindowName'.")]        public async Task<clReadPerfiles> CreatePerfilesAsync(            [GraphQLDescription("Datos necesarios para crear el Perfile.")]            clCreatePerfiles objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Perfile.")]            IPerfilesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.CreatePerfiles(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("updatePerfiles")]        [GraphQLDescription("Actualiza los campos especificados de un Perfile existente.")]        public async Task<clReadPerfiles?> UpdatePerfilesAsync(            [GraphQLDescription("Datos del Perfile a actualizar.")]            clUpdatePerfiles objInput,            [Service]            [GraphQLDescription("Servicio para operaciones de Perfile.")]            IPerfilesService objService,
            [Service] IGraphQLContextService objCtx        )        {            var (userId, windowName) = objCtx.GetRequestContext();            return await objService.UpdatePerfiles(objInput, userId, windowName);        }        [Authorize]        [GraphQLName("deletePerfiles")]        [GraphQLDescription("Elimina un Perfile por su ID.")]        public async Task<bool> delPerfilesAsync(            [GraphQLDescription("ID del Perfile a eliminar.")]            int nPerfilesID,            [Service]            [GraphQLDescription("Servicio para operaciones de Perfile.")]            IPerfilesService objService        )        {            return await objService.DeletePerfiles(nPerfilesID);        }    }}